pub fn next_delay(attempt: u32, config: &RetryConfig) -> u64 {
    // `attempt` is 1-based, so the first retry must shift by 0 to stay at
    // `base_delay_ms`. Saturating arithmetic keeps large attempt numbers at
    // the cap instead of wrapping to zero after bits shift out of the u64.
    let shift = attempt.saturating_sub(1).min(63);
    let raw = config.base_delay_ms.saturating_mul(1u64 << shift);
    raw.min(config.max_delay_ms)
}

